import random
class LRUApprox:
    def __init__(self, maxkeys):
        self.data = {}
        self.maxkeys = maxkeys
        self.clock = 0
    def _now(self):
        self.clock += 1
        return self.clock
    def put(self, k):
        if k in self.data:
            self.data[k] = self._now()
            return
        if len(self.data) >= self.maxkeys:
            sample = random.sample(list(self.data.keys()), min(5, len(self.data)))
            victim = min(sample, key=lambda x: self.data[x])
            del self.data[victim]
            print(f"    内存满, 采样候选, 淘汰最久未用 {victim}")
        self.data[k] = self._now()
    def touch(self, k):
        if k in self.data:
            self.data[k] = self._now()

random.seed(1)
c = LRUApprox(maxkeys=3)
for k in ["a", "b", "c"]:
    c.put(k)
c.touch("a"); c.touch("b")
print("近似 LRU 淘汰 (allkeys-lru, 采样5):")
print("  当前:", c.data)
c.put("d")
c.put("e")
print("  最终:", c.data)
print("  Redis 用随机采样近似 LRU, 而非全局严格 LRU, 节省开销")
